def re_arrange_array(arr):
    """
    Rearranges the elements of the given array so that all negative elements appear before positive ones.
    The relative order of elements is not guaranteed to be preserved.
    """
    left = 0
    right = len(arr) - 1

    while left <= right:
        if arr[left] < 0:
            left += 1
        elif arr[right] >= 0:
            right -= 1
        else:
            arr[left], arr[right] = arr[right], arr[left]
            left += 1
            right -= 1

def second_smallest(lst):
    if len(lst) < 2:
        raise ValueError("List must contain at least two elements")
    unique_vals = set(lst)
    if len(unique_vals) < 2:
        raise ValueError("List must contain at least two distinct elements")
    sorted_vals = sorted(unique_vals)
    return sorted_vals[1]

